// PART 6 pool, patio and garden details (plan.md ticks 23, 24, 26): the kidney pool in its reserved cells (liner, water,
// quartz coping), three loungers and a patio table on the patio (z=26..28), a palm on the back lawn, four garden lamps
// (two by the entry path, two by the pool) and short grass on the lawns. Writes only into air; the helpers do the work.
import { rng, kidney_pool, lounger, patio_table, palm, garden_lamp, GRASS_BLOCK, SHORT_GRASS } from "../vocab.mjs";

// plan.md: kidney pool top-left cell (x=13, z=29); patio loungers and table on the row z=27; palm (29,31)
const POOL_AT = [13, 29];
const LOUNGERS = [[12, 27], [20, 27], [24, 27]]; // head cell; the foot sits one cell east (axis x, d=1)
const PATIO_TABLE = [16, 27];                    // chairs at x=15 and x=17
const PALM = [29, 31];
// garden lamps: flanking the entry path (x=17, x=21 at z=5) and two by the pool on the lawn
const LAMPS = [[17, 5], [21, 5], [10, 30], [25, 30]];
const GRASS_DENSITY = 0.35;

export function build(g) {
  const out = { pool: kidney_pool(g, ...POOL_AT) };
  out.loungers = LOUNGERS.map(([x, z]) => lounger(g, x, z, "x", 1));
  out.table = patio_table(g, PATIO_TABLE[0], PATIO_TABLE[1], 1, "x");
  out.palm = palm(g, ...PALM);
  out.lamps = LAMPS.map(([x, z]) => garden_lamp(g, x, z));

  // short grass on the lawns: any grass_block cell at y=0 with air above it, sparse and seeded
  const rand = rng(6);
  let grass = 0;
  for (let x = 0; x < 34; x++) for (let z = 0; z < 34; z++) {
    if (g.blockAt(x, 0, z) !== `minecraft:${GRASS_BLOCK}`) continue;
    if (!g.isAir(x, 1, z) || rand() >= GRASS_DENSITY) continue;
    g.set(x, 1, z, SHORT_GRASS);
    grass++;
  }
  out.grass = grass;
  return out;
}

